window.LEELA_KAIVALYA_HINDI = [
{title:'ध्यान से प्राप्त ज्ञान प्रामाणिक बनता है',summary:'पूजा, भजन और ध्यान को वास्तविक अभ्यास से समझना चाहिए। सत्य या स्थायी आनंद की आकांक्षा खोज आरंभ कर सकती है, पर अकेली आकांक्षा पर्याप्त नहीं। साधक अपने उद्देश्यों और दृष्टिकोण की जाँच करे और बिना अनुभव निर्णय देने के स्थान पर साधना अपनाए।\n\nकुछ लोग आलोचना और बहुत पढ़ने में लगे रहते हैं, पर अभ्यास का पहला कदम भी नहीं उठाते। ध्यान से मिला थोड़ा ज्ञान भी केवल पुस्तकीय विद्या से श्रेष्ठ है, क्योंकि वह व्यक्तिगत अनुभव से प्रमाणित है। बढ़ती समझ के साथ तर्क दूसरों से विवाद करने के बदले अपनी निम्न प्रवृत्तियाँ जीतने की ओर मुड़ता है। आत्मविश्वास इस मार्ग में प्रवेश का आधार है; आध्यात्मिक अध्ययन की कसौटी आंतरिक परिवर्तन है।',quiz:[['साधना का मूल्य किससे स्थापित होता है?',['अभ्यास द्वारा व्यक्तिगत अनुभव','केवल विवाद','पुस्तकों की संख्या','लोकप्रतिष्ठा'],'अनुशासन की गहराई पर निर्णय से पहले अभ्यास करना चाहिए।'],['साधक आरंभ में क्या जाँचे?',['दूसरों का धन','अपनी आकांक्षाएँ और दृष्टिकोण','केवल सामाजिक पद','श्रोताओं की संख्या'],'साधना के निर्णय के साथ आत्मपरीक्षण आवश्यक है।'],['संचित विद्वत्ता से बढ़कर क्या है?',['आलोचनाकौशल','वक्ता की प्रसिद्धि','ध्यान से मिला थोड़ा ज्ञान','केवल पन्ने पलटना'],'अभ्यासरहित जानकारी से अनुभूत ज्ञान श्रेष्ठ है।'],['साधक का तर्क किस ओर मुड़े?',['प्रतिद्वंद्वी धार्मिक समूह','दूसरों की संपत्ति','प्रशंसा की खोज','अपनी निम्न प्रवृत्तियाँ'],'निरर्थक विवाद का स्थान आंतरिक परिवर्तन लेता है।'],['इस मार्ग में प्रवेश के लिए क्या आवश्यक है?',['आत्मविश्वास','दंभ','ईर्ष्या','प्रशंसा पर निर्भरता'],'आत्मविश्वास सच्चे आध्यात्मिक प्रयत्न को सहारा देता है।']]},
{title:'आध्यात्मिक जीवन का आनंद और शांति',summary:'जिम्मेदारियों के बोझ, अयोग्यता की भावना या श्रद्धा की कमी से निराश व्यक्ति को क्षणिक सुख से आगे देखना चाहिए। मानव जीवन सीमित है, इसलिए मन की शांति और आदर्श जीवन के लिए सचेत प्रयास उचित है। क्रूरता या पतित आचरण में गिरने के बदले मनुष्य अपने श्रेष्ठ मानवीय गुण सुरक्षित रखे।\n\nआध्यात्मिक जीवन यह संकल्प दृढ़ करता है। बुद्धि और व्यावहारिक कौशल भी महत्त्वपूर्ण हैं; वे न्याय, सद्गुण और आध्यात्मिक उत्कृष्टता के साथ दैनिक समस्याओं का समाधान करते हैं। दोनों पक्षी के दो पंखों या गाड़ी के दो पहियों जैसे हैं। संसार का अनुभव और समझ उच्च मार्ग की महत्ता पहचानने में सहायक हैं। आध्यात्मिक आकांक्षा जिम्मेदार और सक्षम जीवन से जुड़ी है।',quiz:[['क्षणिक सुख से आगे क्या लक्ष्य है?',['केवल सार्वजनिक पद','हर जिम्मेदारी से छुटकारा','अधिक प्रतिद्वंद्विता','मन की शांति और आदर्श जीवन'],'सीमित जीवन में स्थायी मूल्य पर ध्यान है।'],['मनुष्य कौन-सा संकल्प रखे?',['श्रेष्ठ मानवीय गुण बनाए रखना','हर आवेग का अनुसरण','किसी भी मूल्य पर आराम','दूसरों की उपेक्षा'],'साधना पतित आचरण से बचने में सहायक है।'],['कौन-सी दो व्यावहारिक क्षमताएँ प्रमुख हैं?',['धन और प्रसिद्धि','बुद्धि और कौशल','गति और प्रदर्शन','पद और प्रभाव'],'ये दैनिक जीवन की समस्याओं से निपटने में सहायक हैं।'],['दोनों की संयुक्त आवश्यकता का उदाहरण क्या है?',['अकेला पत्ता','बंद द्वार','पक्षी के दो पंख या गाड़ी के दो पहिए','मिटती छाया'],'संतुलित प्रगति के लिए दोनों चाहिए।'],['उच्च मार्ग की महत्ता क्या स्पष्ट कर सकता है?',['चिंतन से इनकार','केवल प्रशंसा की खोज','हर कर्तव्य की उपेक्षा','संसार का अनुभव और समझ'],'सांसारिक समझ और आध्यात्मिक आकांक्षा जुड़ी हैं।']]},
{title:'जगत एक दिव्य लीला है',summary:'जगत आकर्षक है, पर क्षणभंगुर है। उसकी अनित्यता पहचानने से दिव्य लीला और दृश्यों के नीचे नित्य सत्य का बोध खुलता है। धन, सत्ता, विद्या या कौशल जमा करने से ही यह नहीं मिलता। चेतना की शुद्धि और आध्यात्मिक खोज में लगन चाहिए।\n\nसंदेह, जड़ मत, निरर्थक तर्क और आधारहीन कल्पनाएँ इस खोज में बाधाएँ हैं। लीला कैवल्य वाहिनी का उद्देश्य इन्हें दूर करके आध्यात्मिक प्रगति और आनंद को प्रोत्साहित करना बताया गया है। मूल घोषणा में श्रृंखला का आरंभ युगादि पर बताया गया था। बदलते दृश्यों के मोह से हटकर उनके नित्य आधार की निष्कपट, शुद्ध खोज मुख्य आमंत्रण है।',quiz:[['यहाँ जगत कैसा कहा गया है?',['हर दृश्य में अविकारी','सुरक्षा का अंतिम स्रोत','मोहक पर क्षणभंगुर','ईश्वर से स्वतंत्र'],'आकर्षक दृश्य नित्य सत्य से अलग हैं।'],['अनित्यता पहचानने से क्या बोध होता है?',['धन नित्य है','पद पर अधिक निर्भरता','हर विचार का निषेध','दिव्य विश्वलीला का बोध'],'उपदेश दृश्यों से परे नित्य सत्ता की ओर ले जाता है।'],['इस बोध के लिए क्या आवश्यक है?',['चेतना की शुद्धि और गंभीर खोज','केवल सत्ता','केवल धन','केवल विद्वत्ता'],'बाहरी उपलब्धि आंतरिक तैयारी का विकल्प नहीं।'],['कौन-सी बाधा कही गई है?',['सच्चा अभ्यास','निरर्थक तर्क','नैतिक स्पष्टता','स्थिर आकांक्षा'],'श्रृंखला ऐसी बाधाएँ दूर करने हेतु प्रस्तुत है।'],['घोषित आरंभ किस पर्व पर है?',['कोई पर्व नहीं','फसल मेला','युगादि','राजकीय वर्षगाँठ'],'यह मूल घोषणा का उल्लेख है।']]},
{title:'वेद ईश्वर का श्वास है',summary:'संवाद में साधक पूछता है कि वेद को प्रमाण क्यों माना जाता है। साई उसे दिव्य ज्ञान का भंडार बताते हैं जिसका सत्य भूत, वर्तमान और भविष्य से नहीं बदलता। उसका उद्देश्य लोककल्याण तथा मानव समाज की शांति और सुरक्षा भी है।\n\nऋषियों की प्रबुद्ध चेतना वेदवचनों के सत्य को ग्रहण करने में सक्षम हुई। इसलिए उनका स्रोत व्यक्तिगत कल्पना के बजाय दिव्य बताया गया है। वचन को ईश्वर का श्वास कहना इसी पवित्र उत्पत्ति को व्यक्त करता है। वेद का महत्त्व नित्य सत्य, प्रबुद्ध ग्रहण और कल्याणकारी जीवन के मार्गदर्शन पर आधारित है।',quiz:[['वेद की परिभाषा क्या है?',['राजाज्ञाओं का संग्रह','दिव्य ज्ञान का भंडार','व्यापार का लेखा','बदलती रुचियों का समूह'],'उत्तर उसके आध्यात्मिक विषय से आरंभ होता है।'],['समय के साथ उसके सत्य का क्या संबंध है?',['केवल वर्तमान रुचि पर निर्भर','केवल एक क्षण के लिए','भूत, वर्तमान या भविष्य उसे नहीं बदलते','हर मत के साथ बदलता है'],'स्थायी सत्य उसकी प्रामाणिकता का आधार है।'],['वेदवचन किसने ग्रहण किए?',['सत्ताकांक्षी शासकों ने','केवल व्यापारियों ने','अभ्यास से बचते आलोचकों ने','प्रबुद्ध चेतना वाले ऋषियों ने'],'शुद्ध क्षमता ने सत्य ग्रहण करना संभव किया।'],['वेद से कौन-सा सामाजिक लाभ जुड़ा है?',['शांति और सुरक्षा','अनंत स्पर्धा','धन का गर्व','समूहों में द्वेष'],'उपदेश मानव कल्याण से जुड़ा है।'],['वचन की दिव्य उत्पत्ति का रूपक क्या है?',['राजमुकुट','ईश्वर का श्वास','बाजार की घंटी','यात्री का नक्शा'],'यही शीर्षक और व्याख्या का आधार है।']]},
{title:'वेद समस्त आध्यात्मिक ज्ञान समेटता है',summary:'साधक पूछता है कि क्या वेद सामान्य भौतिक जीवन पर भी प्रकाश डालते हैं। उत्तर उन्हें भलाई पाने और हानि से बचने की मानवीय इच्छा से जोड़ता है। उनके विधि-निषेध बताते हैं कि क्या करना और क्या छोड़ना चाहिए। इस प्रकार मार्गदर्शन इस लोक और परलोक दोनों से संबंधित है।\n\nवेद शब्द विद् अर्थात जानना से निकला बताया गया है और आध्यात्मिक ज्ञान समेटता है। ऐसी प्रज्ञा मानव जीवन का विशिष्ट अवसर है। वेद दैनिक चुनावों से अलग विषय नहीं, पूरे जीवन का मार्गदर्शन है। ज्ञान तब उद्देश्य पूरा करता है जब वह आचरण की दिशा तय करे।',quiz:[['साधक की चिंता क्या है?',['दैनिक भौतिक जीवन का मार्गदर्शन','पांडुलिपियों का मूल्य','मंदिरों की रचना','पर्वों के नाम'],'प्रश्न सामान्य जीवन से वेद के संबंध पर है।'],['विधि-निषेध क्या अलग करते हैं?',['आत्मा के धनी और गरीब प्रकार','करणीय और अकरणीय','पुराने और नए वस्त्र','संगीत के स्वर'],'वे हित पाने और अहित छोड़ने का मार्ग बताते हैं।'],['वेद यहाँ किस क्षेत्र को संबोधित करता है?',['केवल अनुष्ठान','केवल व्यापार','भौतिक और आध्यात्मिक जीवन','केवल व्याकरण'],'उत्तर इस लोक और परलोक दोनों को समेटता है।'],['वेद की धातु क्या है?',['यज्, पूजा करना','अद्, खाना','अरण्य, वन','विद्, जानना'],'व्युत्पत्ति ज्ञान से संबंध बताती है।'],['कौन-सी मानवीय क्षमता प्रमुख है?',['आध्यात्मिक प्रज्ञा','केवल संपत्ति','शरीर का आकार','लोकप्रसिद्धि'],'प्रज्ञा मानव अवसर के केंद्र में है।']]},
{title:'एक वेद के पाँच संहिता-संग्रह',summary:'वेद असीम है, फिर भी मूलतः एक था। उसकी विशालता सामान्य विद्यार्थियों को कठिन और निरुत्साहित करती थी। संग्रहों में विभाजन इस विरासत को सुलभ बनाता है; यह विरोधी आध्यात्मिक स्रोतों का संकेत नहीं। संवाद स्तुतियों, गेय मंत्रों और अन्य मंत्रों के समूह बताता है।\n\nव्यास को वेद के चार भाग और पाँच संहिताएँ व्यवस्थित करने का श्रेय दिया गया है। वे पराशर के पुत्र, महान ऋषि और नारायण के अंशावतार बताए गए हैं। उनका कार्य मानव कल्याण तथा धर्ममय जीवन के लिए था। चार वेदों की पाँच संहिताएँ होने का कारण अगले खंड में है; यहाँ करुणापूर्ण व्यवस्था द्वारा अध्ययन संभव बनाना मुख्य विषय है।',quiz:[['आरंभ में कितने वेद थे?',['पाँच','नौ','तैंतीस','एक'],'बाद के विभाग मूल एकता के हैं।'],['विभाजन क्यों उपयोगी था?',['विशालता विद्यार्थियों को कठिन और निरुत्साहित करती थी','मूल उपदेश मूल्यहीन था','हर क्षेत्र को विरोधी सत्य चाहिए था','अध्ययन रोकना था'],'व्यवस्था ने सामग्री सुलभ बनाई।'],['संग्रह किसने व्यवस्थित किए?',['वाल्मीकि','व्यास','कालिदास','वसिष्ठ'],'यह लोककल्याणकारी कार्य व्यास का बताया गया है।'],['गेय ऋचाएँ किस संहिता में हैं?',['अथर्वसंहिता','यजुःसंहिता','सामसंहिता','ऋक्संहिता'],'संगीतात्मक गायन इसकी विशेषता है।'],['व्यास किसके पुत्र बताए गए हैं?',['प्रह्लाद','हिरण्यकशिपु','अथर्वन्','पराशर ऋषि'],'यह उनके परिचय में दिया गया है।']]},
{title:'वेद के विभाग आध्यात्मिक अवस्थाओं के अनुरूप हैं',summary:'यजुर्वेद के कृष्ण और शुक्ल रूप होने से पाँचवीं संहिता बनती है। ब्राह्मण, आरण्यक और उपनिषद् तीन पूरक प्रकार के ग्रंथ हैं। वे चेतना की अलग अवस्थाओं का मार्गदर्शन करते हैं ताकि विविध साधकों को लाभ हो। उनका अंतर विरोध नहीं, उपयुक्त मार्गदर्शन का रूप है।\n\nब्राह्मण मंत्रविधि, अनुष्ठान और यज्ञकर्म समझाते हैं। आरण्यक का नाम अरण्य अर्थात वन से है; वे शांत अध्ययन और ध्यान के लिए हैं, विशेषतः विद्यार्थी और गृहस्थ जीवन के बाद वानप्रस्थ के लिए। ब्रह्मकांड को कर्मकांड और सदाचार के विस्तार से भी जोड़ा गया है। साहित्य कर्तव्य, आंतरिक तैयारी और गहरी समझ को जोड़ता है।',quiz:[['चार वेदों की पाँच संहिताएँ क्यों हैं?',['ऋग्वेद के पाँच भाग','सामवेद की कोई संहिता नहीं','यजुर्वेद की कृष्ण और शुक्ल संहिताएँ','अथर्व को बिना कारण दो बार गिना है'],'यजुर्वेद के दो संग्रह अतिरिक्त संख्या बताते हैं।'],['तीन पूरक ग्रंथ कौन हैं?',['पुराण, कविता और राजाज्ञा','स्तोत्र, पंचांग और लेखा','मंत्र, पत्र और जीवनी','ब्राह्मण, आरण्यक और उपनिषद्'],'वे अलग चेतनास्तरों से संबंधित हैं।'],['ब्राह्मण क्या समझाते हैं?',['कर्मसूत्र और यज्ञविधियाँ','केवल वनभूगोल','केवल वाद्य','केवल राजवंश'],'वे मंत्रों से जुड़े कर्म स्पष्ट करते हैं।'],['अरण्य का अर्थ क्या है?',['अग्नि','वन','समुद्र','श्वास'],'नाम आश्रमों में शांत अध्ययन से जुड़ा है।'],['आरण्यक विशेषतः किसके लिए हैं?',['अध्ययन से पहले बचपन','केवल शासन','ब्रह्मचर्य और गृहस्थ के बाद वानप्रस्थ','व्यापार-प्रशिक्षण'],'वे अधिक अंतर्मुख जीवन के परिवर्तन का मार्गदर्शन करते हैं।']]},
{title:'उपनिषद् सर्वोच्च अध्यात्म, वेदांत हैं',summary:'उपनिषदों को समझने के लिए बुद्धिपूर्ण विवेक चाहिए। धर्म, अर्थ, काम और मोक्ष चार पुरुषार्थ बताए गए हैं। पहले तीन से संबंधित विद्या और मुक्ति की ओर ले जाने वाली उच्च विद्या में भेद किया गया है।\n\nइस विवेचन में उपनिषद् वेदांत हैं। पवित्र शब्द कंठस्थ करना उनका पूरा मूल्य नहीं। ज्ञान की पूर्णता के लिए उपदेश समझना और आत्मसात् करना आवश्यक है। अध्ययन का सर्वोच्च उद्देश्य याद किए ग्रंथ का स्वामित्व नहीं, उस सत्य की वास्तविक समझ है जिसकी ओर वह संकेत करता है।',quiz:[['उपनिषद् समझने के लिए क्या चाहिए?',['केवल धन','बुद्धिपूर्ण विवेक','प्रतिष्ठा','केवल तेज पाठ'],'विवेक पर बल है।'],['कितने पुरुषार्थ बताए गए हैं?',['दो','पाँच','चार','नौ'],'धर्म, अर्थ, काम और मोक्ष चार हैं।'],['उच्च विद्या किस लक्ष्य से जुड़ी है?',['केवल समृद्धि','केवल मर्यादित इच्छा','केवल भौतिक सुरक्षा','मुक्ति'],'मोक्ष उच्च लक्ष्य है।'],['यहाँ वेदांत किसे कहा है?',['उपनिषद्','राजवृत्तांत','व्यापार-पुस्तिकाएँ','वाद्ययंत्र'],'संवाद सीधा यह संबंध बताता है।'],['कंठस्थ करने से आगे क्या आवश्यक है?',['लोकप्रशंसा','समझ और आत्मसात् करना','अधिक संपत्ति','नई उपाधि'],'ज्ञान भीतर समझा जाना चाहिए।']]},
{title:'वेद के नौ नाम उसके गुण बताते हैं',summary:'वेद के नौ नाम हैं—श्रुति, अनुश्रव, त्रयी, आम्नाय, नामाम्नाय, छंदस्, स्वाध्याय, आगम और निगमागम। श्रुति सुनने से जुड़ी है: शिष्य शिक्षक का पाठ ध्यान से सुनकर स्वर-मात्राओं सहित दोहराता है। अनुश्रव भी क्रमागत श्रवण से परंपरा चलने को व्यक्त करता है।\n\nत्रयी तीन प्रारंभिक संहिताओं का स्मरण है। आम्नाय और नामाम्नाय निरंतर अध्ययन, छंदस् काव्य-छंद और स्वाध्याय पीढ़ियों में शिक्षण-अध्ययन को बताता है। आगम और निगमागम उद्गम या प्रकट होने से संबंधित हैं। दिव्य श्वास से उत्पन्न वेद के अक्षर और शब्द मंत्र माने गए हैं। ये नाम ग्रहण, रूप, संरक्षण और पवित्रता के पहलू बताते हैं।',quiz:[['श्रुति का अर्थ क्या है?',['जो सुना गया','जो खरीदा गया','जो भुलाया गया','जो चित्रित हुआ'],'नाम गुरु से सावधान श्रवण बताता है।'],['शिष्य मंत्र के साथ क्या दोहराए?',['गुरु की संपत्ति','स्वर के उतार-चढ़ाव','सामाजिक उपाधि','लिखित हस्ताक्षर'],'ध्यान से सुनने पर पाठविधि सुरक्षित रहती है।'],['त्रयी का अर्थ क्या है?',['पाँच','नौ','तीन','अनंत'],'यह ऋक्, यजुः और साम की प्रारंभिक प्रमुखता बताता है।'],['काव्य-छंद किस नाम से जुड़ा है?',['आगम','श्रुति','त्रयी','छंदस्'],'छंद का गेय रूप से संबंध बताया गया है।'],['स्वाध्याय यहाँ क्या बताता है?',['पीढ़ियों में शिक्षण और अध्ययन से संचार','हर अध्ययन पर रोक','देवताओं की संख्या','अग्नि का भौतिक रूप'],'व्याख्या निरंतर अध्ययन से संरक्षण पर है।']]},
{title:'वैदिक मंत्र मुक्ति के शक्तिशाली साधन हैं',summary:'मंत्र को मनन तथा पार लगाने या मुक्त करने की शक्ति से समझाया गया है। उसके शब्द कर्म के अर्थ और उद्देश्य को मन में बनाए रखें। अर्थ समझे बिना यांत्रिक जप से पूरा लाभ नहीं मिलता। अर्थ और महत्त्व का सजग बोध आवश्यक है।\n\nशाखा वेद का अंग है। वृक्ष, शाखा, टहनी और पत्ते बताते हैं कि भाग बड़े समग्र से कैसे जुड़े हैं। अनेक शाखाएँ अध्ययन और अभ्यास से लुप्त हुई हैं, जबकि वैदिक ज्ञान अत्यंत विशाल है। ऋषियों ने इसलिए चुनिंदा शाखाओं का गहरा अध्ययन किया। शिक्षा का मूल्य केवल पाठ की मात्रा नहीं, चिंतन, समझ और अभ्यास से जुड़ा है।',quiz:[['मन् किससे संबंधित है?',['संपत्ति संचय','शारीरिक यात्रा','प्रशंसा की खोज','मानसिक मनन या खोज'],'मंत्र की व्याख्या विचारपूर्ण ध्यान से है।'],['त्र किस शक्ति से जुड़ा है?',['पार लगाना, बचाना या मुक्त करना','प्रतिस्पर्धा बढ़ाना','समय मापना','शाखाएँ गिनना'],'यह मंत्र की व्याख्या पूर्ण करता है।'],['यांत्रिक पाठ की आलोचना क्यों है?',['शब्द कम हैं','अर्थ और महत्त्व की उपेक्षा होती है','श्रोता नहीं हैं','वह सदा मौन है'],'पूर्ण लाभ के लिए सजग समझ चाहिए।'],['शाखा क्या है?',['आभूषण','राजकीय उपाधि','वेद से निकला अंग या शाखा','भौतिक ज्वाला'],'वृक्ष का उदाहरण भाग और समग्र जोड़ता है।'],['ऋषियों ने चुनिंदा शाखाओं पर ध्यान क्यों दिया?',['किसी में उपदेश नहीं','केवल एक थी','अध्ययन अभ्यास से असंबंधित था','वैदिक विरासत विशाल है'],'विशाल ज्ञान में गहरा अध्ययन बताया गया है।']]},
{title:'ऋग्वेद में अग्नि की विशेष स्तुति है',summary:'ऋग्वेद दिव्य रूपों की स्तुतियों का संग्रह है; यहाँ तैंतीस देवता महत्त्वपूर्ण बताए गए हैं। सूर्य की किरणें भुजाएँ और अग्नि की लपटें जिह्वाएँ हैं। घर्षण से उत्पन्न अग्नि अपनी जनक लकड़ी को खाती है; लकड़ी चलाने वाली दस उँगलियाँ सेवक हैं। धुआँ उसकी पताका है, इसलिए नाम धूमकेतु है।\n\nयज्ञ में अग्नि देवताओं को लाती और आहुतियाँ पहुँचाती है, इसलिए यज्ञसारथि कहलाती है। शरीर के भीतर और बाहर जीवन का पोषण करने से वह गृहपति भी है। अग्नि प्राणियों, जातियों और समुदायों में भेद नहीं करती, इसलिए समान मित्र है। रूपक अनुष्ठान को अग्नि के दैनिक महत्त्व और सार्वभौमता से जोड़ते हैं।',quiz:[['इस वर्णन में कितने देवता महत्त्वपूर्ण हैं?',['चार','नौ','तैंतीस','सत्रह'],'आरंभ में यही संख्या है।'],['अग्नि के दस सेवक क्या हैं?',['दस पर्वत','दस नदियाँ','दस यज्ञभवन','लकड़ी चलाने वाली दस उँगलियाँ'],'उदाहरण घर्षण से अग्नि उत्पन्न करने का है।'],['धूमकेतु नाम क्यों है?',['धुआँ अग्नि की पताका है','जल वाहन है','सोना आभूषण है','वायु मुकुट है'],'धुआँ अग्नि की उपस्थिति बताता है।'],['यज्ञसारथि का अर्थ क्या है?',['समुद्र का शासक','यज्ञ का सारथि','धन का रक्षक','व्याकरण का शिक्षक'],'अग्नि देवताओं और आहुतियों को पहुँचाती है।'],['अग्नि समान मित्र क्यों है?',['एक समूह की है','धन का पक्ष लेती है','प्राणी, जाति और समुदाय में भेद नहीं करती','केवल विद्वानों की सेवा करती है'],'निष्पक्षता अंतिम प्रमुख गुण है।']]},
{title:'ऋग्वेद सार्वभौम एकता घोषित करता है',summary:'ऋग्वेद का केंद्रीय उपदेश एकता बताया गया है। मनुष्य एक परम सत्ता की अभिव्यक्तियाँ हैं, इसलिए उनके उद्देश्य, भाव और सत्यनिष्ठा श्रेष्ठ तथा साझा हों। मानव एकता केवल आधुनिक आदर्श नहीं; उसका स्थान वैदिक शिक्षा में है।\n\nहर व्यक्ति की आत्मा वही एक सत्य है जो अनेक रूपों में दिखता है। आरोपित विभाजन जीवन संकुचित करके संघर्ष बढ़ाते हैं। इसलिए संकीर्ण सीमाएँ पुष्ट करने के बदले उन्हें पार करने वाली समावेशी समझ चाहिए। केवल एकता कहना नहीं, इच्छाएँ, विचार और आचरण उस सत्य द्वारा व्यक्त सामूहिक हित की ओर ले जाना आवश्यक है।',quiz:[['ऋग्वेद का केंद्रीय उपदेश क्या है?',['सामाजिक स्पर्धा','एकता','भौतिक संचय','अलगाव'],'सार्वभौम एकता सर्वोच्च आदर्श है।'],['विचार किस ओर हों?',['निजी श्रेष्ठता','शत्रुता','शुभ भाव और शुभ उद्देश्य','केवल प्रदर्शन'],'साझा श्रेष्ठ लक्ष्य उपदेश व्यक्त करता है।'],['मनुष्य एक सत्ता से कैसे जुड़े हैं?',['पूर्णतः असंबंधित हैं','केवल कुछ का आत्मिक आधार है','मूल्य धन पर निर्भर है','उसकी अभिव्यक्तियाँ हैं'],'एकता दिव्य सत्य पर आधारित है।'],['सबकी आत्मा के विषय में क्या कहा है?',['एक ही अनेक रूपों में है','जाति से मूल्य बदलता है','पद पर निर्भर है','केवल शारीरिक गुण है'],'यही समावेशी दृष्टि का आधार है।'],['विभाजन बढ़ने का परिणाम क्या है?',['निश्चित शांति','जीवन का संकुचन और संघर्ष','समदृष्टि','सभी बाधाओं का अंत'],'विभाजन सार्वभौम आदर्श के विपरीत है।']]},
{title:'यजुर्वेद यज्ञ की विधियाँ बताता है',summary:'यजुर्वेद का नाम यज् से जोड़ा गया है, जिसके अर्थों में पूजा और दान हैं। यह यज्ञकर्म बताता है और अध्वरवेद भी कहलाता है। कृष्ण यजुर्वेद को यहाँ ब्रह्म परंपरा और शुक्ल यजुर्वेद को सूर्य परंपरा से जोड़ा गया है।\n\nविवरण उनके क्षेत्रीय प्रसार और समय के साथ अनेक शाखाओं के लोप की चर्चा करता है। पुस्तक के अनुसार कृष्ण की छियासी शाखाओं में चार और शुक्ल की सत्रह में दो उपलब्ध थीं। ये संख्या पुस्तक के परंपरा-वर्णन की हैं। बचा हुआ उपदेश भी ऐसी गहराई दिखाता है जिसे शब्द या कल्पना आसानी से नहीं माप सकते। अध्ययन ग्रंथों की गिनती से बढ़कर आध्यात्मिक मूल्य से परिचय है।',quiz:[['यजुर्वेद की धातु क्या है?',['यज्','विद्','अद्','म्ना'],'पूजा और दान इसके बताए अर्थों में हैं।'],['यहाँ उसका मुख्य विषय क्या है?',['केवल संगीत-लिपि','यज्ञ और अनुष्ठान की विधियाँ','केवल राजइतिहास','केवल चिकित्सा'],'कर्मकांड में उसकी भूमिका समझाई गई है।'],['उसका दूसरा नाम क्या है?',['पृश्निगर्भ','धूमकेतु','अध्वरवेद','सममित्र'],'अध्वर का अर्थ यज्ञ बताया गया है।'],['शुक्ल यजुर्वेद किस परंपरा से जुड़ा है?',['इस तुलना की ब्रह्म परंपरा','अनाम राजा की परंपरा','प्रह्लाद के साथियों की परंपरा','सूर्य या आदित्य परंपरा'],'कृष्ण और शुक्ल इन संबंधों से अलग बताए गए हैं।'],['पुस्तक कितनी शुक्ल शाखाएँ उपलब्ध बताती है?',['दो','चार','सत्रह','छियासी'],'सत्रह प्रमुख शाखाओं में दो बचने का उल्लेख है।']]}
];
window.LEELA_KAIVALYA_HINDI.push(
{title:'वेद में निर्मल ज्ञान है',summary:'पहले बताए नौ नामों के अतिरिक्त भी वेद के अनेक नाम हैं। प्रत्येक उसके उपदेश का कोई पहलू प्रकट करता है। पृश्नि पवित्रता, स्पष्टता और शुचिता से जुड़ा है। पृश्निगर्भ उस सर्वशक्तिमान को बताता है जिसमें निष्कलुष ज्ञान निहित है; वेद उसी ज्ञान को शब्द देता है।\n\nशुद्ध चेतना और निर्मल बुद्धि वाले ऋषियों को मंत्रों के दर्शन की कृपा मिलती है। वे कर्मबंधन से मुक्त होकर ब्रह्म में लीन होते और नया सृष्टिचक्र आरंभ होने पर पुनः प्रकट होते बताए गए हैं। अजन्मा और निष्कलंक शब्द उनकी आत्मिक स्थिति समझाते हैं। तीव्र सत्याकांक्षा का फल प्रकाशन है; शुद्धता, कृपा और प्रत्यक्ष अनुभूति मुख्य विषय हैं।',quiz:[['क्या पहले के नौ नाम ही वेद के सभी नाम हैं?',['हाँ, अन्य नहीं','केवल एक सही है','नाम अर्थहीन हैं','नहीं, अन्य नाम भी गुण बताते हैं'],'खंड अन्य नाम और अर्थ प्रस्तुत करता है।'],['पृश्नि क्या व्यक्त करता है?',['शुद्धता, स्पष्टता और पवित्रता','धन, पद और प्रसिद्धि','क्रोध, भय और द्वेष','गति, वेग और आकार'],'ये गुण पवित्र ज्ञान से उसका संबंध बताते हैं।'],['पृश्निगर्भ किसे बताता है?',['भौतिक वन','निर्मल ज्ञान धारण करने वाला सर्वशक्तिमान','यज्ञ का उपकरण','संगीत का छंद'],'नाम शुद्ध ज्ञान के दिव्य स्रोत का है।'],['मंत्र ग्रहण करने के लिए ऋषियों की तैयारी क्या है?',['केवल मान्यता','केवल संपत्ति','शुद्ध चेतना और निर्मल बुद्धि','केवल विवाद'],'आंतरिक तैयारी से कृपा ग्रहण होती है।'],['वेद किसे शब्दों में प्रकट करता है?',['निजी महत्त्वाकांक्षा','सामाजिक प्रतियोगिता','भौतिक चलन','दिव्य ज्ञान'],'शब्दरूप निष्कलुष ज्ञान व्यक्त करता है।']]},
{title:'पवित्र ऋषियों को मंत्रों का दर्शन होता है',summary:'ब्रह्मयज्ञ वेद का गहन अध्ययन और आचरण है। मंत्र, सत्य, ब्रह्म और धर्म की अंतर्दृष्टि ऋषि को द्रष्टा बनाती है। उनकी दृष्टि से निर्धारित कर्म शांति और समृद्धि के लिए हैं। सत्य की उत्कट चाह तप कही गई है।\n\nतपोज का अर्थ यह नहीं कि तप पहले से न रहे ब्रह्म को बनाता है। ब्रह्म अनादि है; तप उसे साधक के लिए प्रकट करता है। दिव्य उत्तर वचन या वाणी है, जो मंत्र में व्यक्त होता है। पृश्निगर्भ को अन्न, जल, अमृत और वैदिक ज्ञान के दिव्य आश्रय से भी जोड़ा गया है। तैयारी द्वारा प्रकाशन और नित्य सत्य की रचना अलग हैं।',quiz:[['ब्रह्मयज्ञ क्या है?',['राजसत्ता की खोज','ध्यानरहित सार्वजनिक पाठ','वेद का गहन अध्ययन और आचरण','संपत्ति संचय'],'उत्तर इसे स्वाध्याय से जोड़ता है।'],['ऋषियों के निर्धारित कर्मों का उद्देश्य क्या है?',['साधकों में द्वेष','निजी प्रसिद्धि','कर्तव्य की उपेक्षा','शांति और समृद्धि'],'दृष्टि लोककल्याण के लिए है।'],['तप किसे कहा है?',['सत्य की उत्कट चाह','शारीरिक रूप','केवल धन','विद्वत्ता का गर्व'],'तप गंभीर सत्यखोज है।'],['ब्रह्म के संबंध में तपोज का अर्थ क्या है?',['तप शून्य से ब्रह्म बनाता है','तप से ब्रह्म प्रकट होता है','ब्रह्म का ज्ञात आरंभ है','अस्तित्व के लिए ब्रह्म पूजा पर निर्भर है'],'ब्रह्म की अनादिता स्पष्ट सुरक्षित है।'],['तप का दिव्य उत्तर कैसे बताया है?',['सांसारिक उपाधि','आर्थिक पुरस्कार','ईश्वर का वचन या वाणी','सामाजिक भेद'],'प्रकाशन पवित्र मंत्र से जुड़ा है।']]},
{title:'वेदों में प्रथमज का अर्थ',summary:'प्रथमज अर्थात पहले उत्पन्न वेद का नाम है। यह आदरपूर्ण अध्ययन, सजग उपासना और पवित्र वचन के अर्थ की समझ चाहता है। आंतरिक ध्यान बिना केवल पाठ पर्याप्त नहीं। पूर्वज नाम भी ऐसे उद्गम को बताता है जिसका आरंभ निर्धारित नहीं किया जा सकता।\n\nपरब्रह्म और विश्वसंकल्प की पहली अभिव्यक्ति हिरण्यगर्भ में भेद किया गया है। ब्रह्म नित्य और पूर्ववर्ती है; हिरण्यगर्भ तथा वेद उससे प्रकट होते हैं। आर्ष नाम वेद को सुनने और व्यक्त करने वाले ऋषियों से जोड़ता है। वेद धर्म का स्रोत है, इसलिए उसके कर्तव्य और संयम को निजी इच्छाओं के अनुकूल मोड़ना अनुचित है। श्रद्धा में समझ और जिम्मेदार आचरण दोनों हैं।',quiz:[['प्रथमज का अर्थ क्या है?',['समान मित्र','आदि या पहले उत्पन्न','काव्य-छंद','वन की शिक्षा'],'नाम वेद की पवित्र प्राथमिकता बताता है।'],['पाठ के साथ क्या चाहिए?',['प्रसिद्धि की इच्छा','केवल यांत्रिक गति','विनय और अर्थ तथा निर्देश की सजगता','सामाजिक तुलना'],'पवित्र वचन की सजग सेवा बताई गई है।'],['हिरण्यगर्भ से पूर्व कौन है?',['भौतिक शरीर','यज्ञ-उपकरण','मानव शासक','परब्रह्म'],'ब्रह्म नित्य है।'],['आर्ष नाम वेद को किससे जोड़ता है?',['उसे सुनने और उच्चारित करने वाले ऋषियों से','क्षेत्र के धन से','राजवंश से','भोजन के प्रकार से'],'नाम द्रष्टाओं से संबंध बताता है।'],['किस व्याख्या की आलोचना है?',['विनम्र अध्ययन','शिक्षा को निजी इच्छा के अनुकूल मोड़ना','कर्तव्य पर ध्यान','जिम्मेदार पालन'],'विश्वसनीय अर्थ और स्वार्थपूर्ण विकृति अलग हैं।']]},
{title:'वेद शक्तिशाली दिव्य प्रकाशन हैं',summary:'आर्ष नाम ऋषियों द्वारा वेद के प्रकाशन को बताता है। मंत्र आध्यात्मिक दृष्टि का ऐसा खजाना हैं जो मुक्ति के लिए है। वैदिक ज्ञान का धन भौतिक संपत्ति नहीं, सर्वोच्च लक्ष्य तक ले जाने की शक्ति है।\n\nऋषियों की प्रार्थना बढ़ती संपत्ति और पारिवारिक संचय के बोझ के बदले प्रज्ञा माँगती है। यह संतोष देती और ईश्वरसेवा में काम आती है। धन का मूल्य उसके आत्मिक उपयोग से तय होता है। वेदमाता की कृपा से मिला वैभव समझ, मुक्ति और सेवा में पूर्ण होता है, केवल स्वामित्व में नहीं।',quiz:[['आर्ष यहाँ क्या बताता है?',['ऋषियों द्वारा प्रकाशन','भौतिक वस्तुओं का संग्रह','भौगोलिक सीमा','वाद्ययंत्र'],'नाम ऋषियों की आध्यात्मिक दृष्टि का है।'],['मंत्रों का उद्देश्य क्या है?',['सामाजिक द्वेष','मुक्ति','केवल प्रदर्शन','विवाद बढ़ाना'],'वे आध्यात्मिक कल्याण का खजाना हैं।'],['किस धन को महत्त्व मिला है?',['केवल संपत्ति','सार्वजनिक पद','शक्तिशाली आध्यात्मिक प्रज्ञा','केवल वंशप्रतिष्ठा'],'यह सर्वोच्च लक्ष्य का साधन है।'],['ऋषि प्रार्थना में क्या माँगते हैं?',['केवल असीम पशुधन और संपत्ति','अन्य साधकों पर विजय','शासक की मान्यता','संचय के बोझ के बदले प्रज्ञा'],'आध्यात्मिक समझ से समृद्धि परिभाषित है।'],['इस प्रज्ञा का उपयोग कैसे हो सकता है?',['ईश्वर की सेवा में','केवल आत्मप्रदर्शन','केवल प्रतियोगिता','केवल विवाद'],'सेवा आत्मिक धन की व्याख्या पूर्ण करती है।']]},
{title:'अर्थ की पूर्ण सजगता से वेदपाठ करें',summary:'साधक बिना समझ आदतन पाठ की तुलना ग्रामोफोन से करता है। साई इसे स्वीकार करके बताते हैं कि यांत्रिक ध्वनि मात्र वांछित ज्ञान नहीं देती। पाठ के साथ मंत्र का अर्थ और उसमें व्यक्त भाव का आंतरिक अनुभव होना चाहिए।\n\nसही उच्चारण और सजग सहभागिता साथ हैं। परम खजाना ब्रह्मज्ञान है, जो अर्थ समझने और अनुभव करने वालों को दिव्य कृपा से मिलता है। शब्द दोहराना और उनके महत्त्व को अपनी आध्यात्मिक चेतना का अंग बनाना अलग हैं।',quiz:[['बिना समझ आदतन पाठ का उदाहरण क्या है?',['बहती नदी','तेल वाला दीपक','उगता बीज','ग्रामोफोन का रिकॉर्ड'],'उदाहरण यांत्रिक दोहराव का है।'],['आलोचित पाठ में क्या कमी है?',['अर्थ की सजगता','बड़े श्रोता-समूह','सामाजिक पद','अधिक संपत्ति'],'समस्या भीतर की असावधानी है।'],['शब्दों की समझ के साथ क्या चाहिए?',['गति का गर्व','मंत्रों के भावों का अनुभव','विद्यार्थियों का तिरस्कार','प्रशंसा की इच्छा'],'अर्थ और भाव साथ हों।'],['सर्वोच्च खजाना कौन-सा ज्ञान है?',['केवल व्यापारज्ञान','राजकीय उपाधियों का ज्ञान','ब्रह्मज्ञान','संपत्ति का ज्ञान'],'ब्रह्मविद्या आध्यात्मिक फल है।'],['सजग पाठ से किसकी कृपा जुड़ी है?',['शासक','श्रोता','व्यापारी','ब्रह्म'],'आंतरिक सहभागिता दिव्य कृपा से जुड़ी है।']]},
{title:'नैतिक आचरण से पुष्ट सहज प्रज्ञा ही वैदिक धन है',summary:'प्रश्न है कि कौन-सा धन चाहना चाहिए। वेद उपदेश और सर्वोच्च निधि है। सहज प्रज्ञा सर्वशक्तिमान की प्राप्ति का साधन है, इसलिए आध्यात्मिक लक्ष्य का सच्चा धन है। वह उपासक को पूर्णता और उपासना को सार्थकता देती है।\n\nयह निधि नैतिक आचरण से अलग नहीं। वेद मानव मार्गदर्शन के नियमों के अनुसार अर्जित धन का अनुमोदन करता है। श्रुत्यम् शास्त्र द्वारा वर्णित और अनुशंसित से संबंधित है। आत्मिक धन केवल जानकारी या संचय नहीं, धर्ममय जीवन से पुष्ट प्रज्ञा है; समझ और उसे पाने का तरीका दोनों महत्त्वपूर्ण हैं।',quiz:[['खंड का आरंभ किस प्रश्न से है?',['सबसे बड़ा मंदिर कौन','सबसे ऊँचा वाद्य कौन','कौन-सा धन चाहना चाहिए','सबसे धनी राजा कौन'],'संवाद धन का आध्यात्मिक अर्थ देखता है।'],['परमात्मप्राप्ति का साधन क्या है?',['केवल पद','केवल संपत्ति','लोकप्रशंसा','सहज प्रज्ञा'],'आध्यात्मिक ज्ञान सच्चा धन है।'],['वेद क्या देता है?',['उपदेश','सभी आचरण का विकल्प','केवल प्रसिद्धि का वादा','स्वार्थलाभ की अनुमति'],'मार्गदर्शन सर्वोच्च हित की ओर है।'],['वेद द्वारा स्वीकृत धन की शर्त क्या है?',['किसी भी साधन से मिलना','नैतिक नियमों के पालन से अर्जित होना','केवल मात्रा से मापा जाना','लोकप्रशंसा लाना'],'अर्जन के नैतिक साधन महत्त्वपूर्ण हैं।'],['श्रुत्यम् किससे संबंधित है?',['राजकर','शारीरिक आसन','वेद द्वारा वर्णित और अनुशंसित','ज्वाला का प्रकार'],'वांछित धन शास्त्रीय मार्गदर्शन से जुड़ा है।']]},
{title:'वेद सभी नैतिक नियमों का स्रोत है',summary:'परिवार की सफलता और इच्छापूर्ति सांसारिक समृद्धि हो सकती हैं, पर नैतिक उत्कृष्टता अधिक मूल्यवान धन है। यह वेदसमर्थित धर्ममय कर्म से जुड़ी है। राम धर्म के मूर्त रूप और धर्म सभी प्राणियों के धारक बताए गए हैं।\n\nधारण करने का गुण वेद और परमात्मा दोनों से जुड़ा है। इसलिए धर्ममय आचरण शक्तिशाली पूजा-अर्पण है। विश्व धर्म पर टिका है, जबकि स्वार्थपूर्ण अर्थ उसकी समझ बिगाड़ते हैं। अंत में वेद को सर्वज्ञ ब्रह्म तथा शास्त्र को उसका मूर्त रूप बताया गया है। नैतिक जीवन का आधार निजी सुविधा नहीं, दिव्य धारणशक्ति है।',quiz:[['सांसारिक समृद्धि से ऊपर क्या है?',['लोकप्रसिद्धि','नैतिक उत्कृष्टता','शारीरिक रूप','राजनीतिक प्रभाव'],'सद्गुण श्रेष्ठ धन है।'],['धर्म का मूर्त रूप कौन है?',['हिरण्यकशिपु','कालिदास','राम','पराशर'],'रामायण का यह वर्णन याद किया गया है।'],['धर्म क्या करता है?',['विभाजन बढ़ाता है','हर जिम्मेदारी हटाता है','दंभ को पुरस्कार देता है','सब प्राणियों को धारण करता है'],'धारणशक्ति उसे दिव्यता से जोड़ती है।'],['प्रभावी पूजा-अर्पण क्या है?',['धर्ममय आचरण','स्वार्थपूर्ण अर्थ','सामाजिक द्वेष','सद्गुणरहित प्रदर्शन'],'धर्म स्वयं परमात्मा को अर्पण है।'],['धर्म की समझ क्या बिगाड़ता है?',['नैतिक उत्कृष्टता','मनमानी और स्वार्थ','जिम्मेदार अध्ययन','सत्याचरण'],'निजी लाभ हेतु अर्थ बदलने से सावधान किया गया है।']]},
{title:'स्वाहा देवताओं को आहुति देने का आवाहन है',summary:'स्वाहा केवल अनुष्ठान के अंत की तकनीकी ध्वनि नहीं। वह वाणी से जुड़ी दिव्य उपस्थिति का आवाहन और देवताओं को अर्पण का संकेत है। स्वधा पितरों को अर्पण के लिए है। दोनों उद्देश्यपूर्ण आवाहन हैं, अर्थहीन अतिरिक्त शब्द नहीं।\n\nये वचन अर्पण के अभिप्रेत ग्रहणकर्ता को सचेत और आमंत्रित करते हैं। पवित्र स्तुति प्रगतिशील गुणों और आध्यात्मिक उन्नति के अवसरों से जुड़ी है। विष्णु, प्राणशक्ति और इंद्र के आवाहन उदाहरण हैं। स्वाहुतम् और सुहूर्तम् अर्पण के ठीक से ग्रहण या पाचन की कामना व्यक्त करते हैं। अगला खंड भौतिक दहन और इस पवित्र अर्थ का अंतर स्पष्ट करता है।',quiz:[['स्वाहा किसका आवाहन है?',['वाणी और अर्पण से जुड़ी दिव्य उपस्थिति','सांसारिक उपाधि','संगीत प्रतियोगिता','सामाजिक सीमा'],'शब्द प्रभावशाली आवाहन है।'],['पितरों के अर्पण में कौन-सा शब्द है?',['छंदस्','स्वधा','त्रयी','आर्ष'],'पितृ और देव अर्पण अलग किए गए हैं।'],['आवाहन का कार्य क्या है?',['सारा अर्थ हटाना','अग्नि की ऊँचाई मापना','अभिप्रेत दिव्य ग्रहणकर्ता को सचेत और आमंत्रित करना','उपासक का धन बताना'],'अर्पण सजग रूप से निर्देशित है।'],['उदाहरण में कौन-सा ग्रहणकर्ता है?',['अनाम राजा','ब्रूस','हिरण्यकशिपु','इंद्र'],'इंद्राय स्वाहा दिए उदाहरणों में है।'],['स्वाहुतम् और सुहूर्तम् का आशय क्या है?',['अर्पण अच्छी तरह ग्रहण या पचाया जाए','अर्पण बिल्कुल अछूता रहे','अनुष्ठान भुलाया जाए','शब्द बिना ध्यान दोहरें'],'उत्तर अग्नि के दिव्य कार्य की चर्चा की ओर जाता है।']]},
{title:'अग्नि का भौतिक और दिव्य दोनों रूप है',summary:'साधक कहता है कि मंत्र बिना भी अग्नि आहुति जला देती है। साई बताते हैं कि दृश्य दहन पवित्र अर्थ का पूरा विवरण नहीं। वेद अग्नि का भौतिक कार्य और दिव्य रूप दोनों बताते हैं। अग्नि द्वारा अर्पण सामान्य इंद्रियदृष्टि से परे देवताओं से संबंध का साधन है।\n\nभोक्ता और भोग्य की चर्चा में अग्नि आहुति की ग्रहणकर्ता है। इस वर्णन में आदित्य प्रथम दिव्य सत्ता और जीवों में प्राणाग्नि उसका आध्यात्मिक समकक्ष है। आहुति रखी या स्थापित की जाती है; शब्दावली अनुष्ठान का अदृश्य पक्ष बताती है। भौतिक घटना और उससे जुड़ा आध्यात्मिक अर्थ अलग समझाए गए हैं।',quiz:[['प्रश्न किस निरीक्षण से उठता है?',['अग्नि कुछ नहीं जलाती','सब देवता दिखाई देते हैं','हर आहुति अपरिवर्तित रहती है','मंत्र बिना भी अग्नि आहुति जलाती है'],'प्रश्न दृश्य घटना में मंत्र का अर्थ पूछता है।'],['उत्तर कौन-सा अंतर बताता है?',['अग्नि के भौतिक और दिव्य रूप तथा कार्य हैं','अग्नि का भौतिक कार्य नहीं','केवल दृश्य प्रभाव अर्थपूर्ण है','मंत्र अर्पण से असंबंधित हैं'],'व्याख्या भौतिक दहन से आगे है।'],['आहुति कौन ग्रहण करता है?',['यज्ञपात्र','अग्नि','केवल लकड़ी','दर्शक-समूह'],'अग्नि भोक्ता या ग्रहणकर्ता है।'],['जीवों में आदित्य का समकक्ष क्या है?',['लोकप्रतिष्ठा','शारीरिक आभूषण','जीवन-ऊष्मा या प्राणाग्नि','बोली गई उपाधि'],'सूर्य जीवन की अग्नि से जुड़ा है।'],['यहाँ आहिताय का अर्थ क्या है?',['तीन में बाँटा','क्रम से सुना','छंद से सीखा','रखा या स्थापित किया'],'यह अग्नि में रखे अर्पण से संबंधित है।']]},
{title:'देवता प्रार्थनापूर्ण आहुतियों का उत्तर देते हैं',summary:'दृश्य और अदृश्य अग्नि के संबंध में अग्रि तथा अग्नि नामों का भेद है। अग्रि प्रथम होने से जुड़ा है। आहुति ऐसा अर्पण है जिसमें ईश्वर को ग्रहण करने का निमंत्रण है। अंत का अनुष्ठानिक उच्चार स्वाहा के प्रभाव को पूर्ण करता है।\n\nस्वाहा वाणी की देवी सरस्वती और पवित्र शब्द में आत्मा की अभिव्यक्ति से भी जुड़ी है। भक्तिग्रंथों में परम देवी का गायत्री, स्वाहा और स्वधा से संबंध बताया गया है। समापन, अंत या अंतर्गत होने के अर्थ भी हैं। मुख्य बल भीतर के पवित्र आवाहन पर है, अर्पण को दिशाहीन भौतिक कर्म मानने पर नहीं।',quiz:[['दृष्टिगोचर अग्नि का नाम क्या है?',['त्रयी','पृश्नि','अग्रि','छंदस्'],'इस व्याख्या में दृष्टि से परे पक्ष अग्नि है।'],['अग्रि का संबंधित अर्थ क्या है?',['वन','धन','छंद','प्रथम'],'नाम सृष्टि की प्राथमिकता से जुड़ा है।'],['आहुति का विशेष अर्थ क्या है?',['ईश्वर को ग्रहण करने के निमंत्रण सहित अर्पण','कहीं भी रखी वस्तु','लपटों की गिनती','संगीत का स्वर'],'निमंत्रण केंद्रीय अर्थ है।'],['स्वाहा किस देवी से जुड़ी है?',['केवल मानव शासक','सरस्वती','केवल वनवासी ऋषि','केवल यज्ञसेवक'],'संबंध पवित्र वाणी से है।'],['स्वाहा का अतिरिक्त अर्थ क्या है?',['वृक्ष की शाखा','काव्य-छंद','समापन या अंत','वंशपरंपरा'],'शब्द के अर्थ एक अनुष्ठानिक प्रयोग से व्यापक हैं।']]},
{title:'विभिन्न नामों से एक ईश्वर की उपासना',summary:'अथर्ववेद के नामों में ब्रह्मवेद, अंगिरोवेद, अथर्वांगिरोवेद और भैषज्यवेद हैं। वसिष्ठ की प्रवीणता याद की गई है। उसके मंत्र सिद्धमंत्र कहलाते हैं और पुस्तक उनके प्रभाव बताती है। गायत्री के पवित्र रूप में भी अथर्ववेद का स्थान समझाया गया है।\n\nवृक्ष के रूपक में अथर्व महान वृक्ष है, अन्य तीन वेद तना और शाखाएँ तथा स्मृतियाँ और पुराण पत्ते हैं। चारों वेद सूर्य को अलग नाम देते हैं। ये विवरण प्रतिस्पर्धी अलग दिव्य स्रोत नहीं, जुड़े हुए ज्ञान और विभिन्न नामों से संबोधित एक दिव्य सत्य को दर्शाते हैं।',quiz:[['अथर्ववेद का दूसरा नाम कौन-सा है?',['धूमकेतु','भैषज्यवेद','सममित्र','पृश्निगर्भ'],'इस वेद के कई नाम दिए हैं।'],['किस ऋषि की अथर्वविद्या की प्रवीणता याद की है?',['वाल्मीकि','अंगुलिमाल','वसिष्ठ','भीष्म'],'कालिदास द्वारा वसिष्ठ की प्रशंसा का संदर्भ है।'],['उसके मंत्र क्या कहलाते हैं?',['केवल सांसारिक कहावतें','राजाज्ञाएँ','केवल संगीताभ्यास','सिद्धमंत्र'],'नाम संवाद में बताए प्रभाव व्यक्त करता है।'],['वृक्ष में पत्ते क्या हैं?',['स्मृतियाँ और पुराण','केवल ऋग्वेद','केवल सूर्य','यज्ञाग्नि'],'अन्य वेद उसी रूपक में तना और शाखाएँ हैं।'],['चार वेद किस एक दिव्य उपस्थिति को अलग नाम देते हैं?',['मानव राजा','सूर्य, आदित्य','यज्ञसेवक','विशेष वृक्ष'],'उदाहरण नामों के पीछे एकता पुष्ट करता है।']]},
{title:'अथर्व के तीन अर्थ',summary:'अथर्व का पहला अर्थ स्थिर, अचल स्वभाव वाला व्यक्ति है। शब्द प्राणवायु को सक्रिय करने वाली चेतना और श्वास के अधिपति से भी जुड़ा है। स्थिरता तथा जीवनधारक तत्त्व का संबंध इन अर्थों से बनता है।\n\nअथर्व प्रजापति, प्राणियों के अधिपति, से भी संबद्ध है। यहाँ उन्हें मंथन से चिंगारियाँ उत्पन्न करके पहली बार अग्नि प्रकट करने वाला बताया गया है। अंत में वेदों के क्रम में अथर्व का स्थान अलग है: अन्य कभी प्रथम कहे जाते हैं, पर अथर्व अंतिम कहा गया है। ये संक्षिप्त परिभाषाएँ एक नाम के जुड़े हुए अर्थ हैं।',quiz:[['अथर्व पहले कौन-सा गुण बताता है?',['स्थिरता','चंचलता','दंभ','अधैर्य'],'अचल और स्थिर स्वभाव बताया गया है।'],['प्राणात्मा किसे सक्रिय करती है?',['सामाजिक उपाधियाँ','प्राणवायुएँ','यज्ञभवन','भौतिक आभूषण'],'शब्द जीवनधारक चेतना से जुड़ा है।'],['प्राणपति का अर्थ क्या है?',['धन का शासक','वन का रक्षक','श्वास का अधिपति','छंद का शिक्षक'],'यह अथर्व का एक और संबंध है।'],['प्रजापति का कौन-सा कार्य बताया है?',['वेद की संहिताएँ बनाना','रामायण लिखना','नौ विशेषताओं के नाम देना','मंथन की चिंगारियों से पहली अग्नि प्रकट करना'],'प्रजापति पहली अग्नि-उत्पत्ति से जुड़े हैं।'],['बताए क्रम में अथर्व का स्थान क्या है?',['अंतिम कहा गया है','सदा प्रथम','पूरी तरह छोड़ा गया','छठा वेद'],'यह अन्य वेदों की बदलती प्राथमिकता से भिन्न है।']]},
{title:'ईश्वर और सृष्टि के सौम्य तथा उग्र पक्ष',summary:'अंतिम खंड ईश्वर के शांत और भयंकर रूपों को समझाता है। वही नरसिंह प्रह्लाद के लिए कृपालु और हिरण्यकशिपु के लिए भयावह हैं। प्रकृति में भी दोनों पक्ष हैं। जल जीवन पोषित करता है और विनाशकारी भी हो सकता है; एक सत्य के अनुभव भिन्न हो सकते हैं।\n\nभोजन में सात्त्विक, राजसिक और तामसिक गुण बताए गए हैं। लाभकारी उपयोग के लिए विवेक और संयम चाहिए। अन्न को अद् अर्थात खाना से समझाकर बताया है कि वह खाया जाता है और दुरुपयोग करने वाले को खा भी सकता है। अथर्वन् और अंगिरस ने मंत्रों का यह द्वैत पक्ष देखा। सौम्य या उग्र रूपों के पीछे उनका उद्देश्य आत्मा प्रकट करना तथा मानवता की शांति और समृद्धि है।',quiz:[['ईश्वर के कौन-से दो पक्ष हैं?',['धनी और गरीब','युवा और वृद्ध','विद्वान और अविद्वान','शांत और भयंकर'],'उदाहरण अलग प्रभाव समझाते हैं।'],['प्रह्लाद के लिए नरसिंह कैसे हैं?',['कृपालु और कल्याणकारी','उसके प्रति विनाशकारी शत्रु','केवल उदासीन','हर अर्थ में अदृश्य'],'वही रूप हिरण्यकशिपु के लिए भयावह है।'],['जीवनदायी और विनाशकारी प्राकृतिक उदाहरण क्या है?',['लिखित उपाधि','जल','काव्य-छंद','सोने की थाली'],'उदाहरण सृष्टि में द्विपक्षीय प्रभाव दिखाता है।'],['भोजन के कौन-से गुण हैं?',['श्रुति, छंदस् और आगम','ऋक्, यजुः और साम','सात्त्विक, राजसिक और तामसिक','यम, नियम और आसन'],'ये प्रकार भोजन के प्रभाव समझाते हैं।'],['मंत्रों का गहरा उद्देश्य क्या है?',['शत्रुता बढ़ाना','गर्व को पुरस्कृत करना','मानवता बाँटना','आत्मा प्रकट करना और शांति तथा समृद्धि बढ़ाना'],'समापन विविध रूपों को एक आत्मिक उद्देश्य में जोड़ता है।']]}
);
